<!-- This file is generated by AI. -->
<!--
  提交历史对话框: 分支切换 + 提交列表 (展开看详情与文件变更, 支持还原)。

  **状态跨打开保留**: 打开场景差异、按 Esc 关闭都不重置; 只有走底部的「关闭」按钮
  (`manualClose`) 才把状态清空。理由是这个对话框的两个主要出口都是"去看别的东西"
  (点文件开差异、点分支切换), 每次回来都丢掉展开项与滚动位置会让人没法连续查一段历史。

  后端 `git.rs` 给的是 Unix **秒** (`commit.time().seconds()`), 因此所有时间运算都要 `* 1000`
  转成毫秒。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import {
    gitCommitFiles,
    gitLocalBranches,
    gitLog,
    gitRestore,
    gitRestoreAll,
    gitStatus as getGitStatus,
    gitSwitchBranch,
    type GitCommit,
    type GitCommitFile,
  } from '../commands/git';
  import { requestConfirm } from '../confirm';
  import { openGitDiff } from '../git/diff';
  import { refreshGitStatus } from '../git/status';
  import { STATUS_CLASS } from '../git/util';
  import { fs } from '../lib/fs';
  import { appStore } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import Icon from './Icon.svelte';

  let { onClose }: { onClose: () => void } = $props();

  /**
   * 跨打开保留的历史状态。
   *
   * 放在**模块作用域**而不是组件状态里 —— 对话框关闭时组件会卸载, 组件内的状态留不住,
   * 而"关掉再看一眼别处"正是最需要它活下来的场景。
   *
   * 类型写成内联字面量而不是单独的 `interface`: 后者在 `$state` 初始化表达式里会被
   * svelte-check 判成 `never` (属性访问一律报 "does not exist on type 'never'")。
   */
  type HistoryPersist = {
    projectPath: string;
    commits: GitCommit[];
    expanded: string[];
    files: Record<string, GitCommitFile[]>;
    scrollTop: number;
  };
  let persisted: HistoryPersist | null = null;

  const projectPath = $derived(appStore.projectPath);
  const branch = $derived(appStore.gitStatus?.branch ?? null);
  const gitStatus = $derived(appStore.gitStatus);
  const documents = $derived(appStore.documents);

  /**
   * 取本次可复用的缓存。
   *
   * 写成函数而不是把取用逻辑塞进 `$state` 初始化表达式: 那种写法会让 svelte-check 把
   * `persisted` 收窄成 `never`, 下面每个属性访问都报错。
   */
  function reusableCache(path: string | null): HistoryPersist | null {
    if (persisted === null) return null;
    return persisted.projectPath === path ? persisted : null;
  }

  // 初值只在挂载时取一次 (对话框每次打开都是新实例), 这正是我们要的
  // svelte-ignore state_referenced_locally
  const cached: HistoryPersist | null = reusableCache(projectPath);

  let commits = $state<GitCommit[]>(cached?.commits ?? []);
  let branches = $state<string[]>([]);
  let expanded = $state<string[]>(cached?.expanded ?? []);
  let files = $state<Record<string, GitCommitFile[]>>(cached?.files ?? {});
  let loading = $state(true);
  let busy = $state(false);
  let error = $state<string | null>(null);
  /** 提交行的右键菜单 */
  let menu = $state<{ file?: GitCommitFile; commitId: string; x: number; y: number } | null>(null);
  /** 分支选择菜单 */
  let branchMenu = $state<{ x: number; y: number } | null>(null);
  let list: HTMLDivElement | undefined = $state();

  /** 与 `FileTree` 同一套中间省略: 保留开头与扩展名后缀。 */
  function middleEllipsis(text: string, maxLen: number): string {
    if (text.length <= maxLen) return text;
    const dot = text.lastIndexOf('.');
    const hasExt = dot > 0 && dot < text.length - 1;
    const ext = hasExt ? text.slice(dot) : '';
    const stem = hasExt ? text.slice(0, dot) : text;
    const avail = maxLen - ext.length - 3;
    if (avail < 4) return `${text.slice(0, Math.max(1, maxLen - 3))}...`;
    const keepHead = Math.ceil(avail / 2);
    const keepTail = avail - keepHead;
    return `${stem.slice(0, keepHead)}...${stem.slice(stem.length - keepTail)}${ext}`;
  }

  /** 提交时间 (秒 -> 本地时间字符串)。 */
  function formatDate(seconds: number): string {
    const date = new Date(seconds * 1000);
    const pad = (value: number) => String(value).padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
  }

  /** 取路径最后一段 (文件名)。 */
  function baseName(path: string): string {
    return path.split(/[\\/]/).pop() ?? path;
  }

  // 每次打开都同步最新的提交列表; 同一仓库保留展开项、文件详情与滚动位置。
  $effect(() => {
    const path = projectPath;
    if (!path) return;

    let cancelled = false;
    const previous: HistoryPersist =
      persisted?.projectPath === path
        ? persisted
        : { projectPath: path, commits: [], expanded: [], files: {}, scrollTop: 0 };
    if (persisted !== previous) {
      // 换了项目: 清掉上一个项目的残留
      persisted = previous;
      commits = [];
      expanded = [];
      files = {};
    }

    loading = true;
    void (async () => {
      try {
        const fetched = await gitLog(path);
        if (cancelled) return;
        commits = fetched;
        persisted = { ...previous, commits: fetched };
        // 列表渲染完才能设滚动位置
        requestAnimationFrame(() => {
          const element = list;
          const state = persisted;
          if (element && state) element.scrollTop = state.scrollTop;
        });
      } catch (e) {
        if (!cancelled) error = String(e);
      } finally {
        if (!cancelled) loading = false;
      }
    })();

    return () => {
      cancelled = true;
    };
  });

  /** 本地分支列表 (切换分支后要重取)。 */
  async function loadBranches(): Promise<void> {
    const path = projectPath;
    if (!path) return;
    try {
      branches = await gitLocalBranches(path);
    } catch (e) {
      error = String(e);
    }
  }

  $effect(() => {
    void projectPath;
    void loadBranches();
  });

  function onScroll(): void {
    if (persisted && list) persisted.scrollTop = list.scrollTop;
  }

  /** 底部「关闭」按钮: 这是唯一会重置状态的出口。 */
  function manualClose(): void {
    persisted = null;
    onClose();
  }

  async function toggle(id: string): Promise<void> {
    const path = projectPath;
    if (!path) return;
    const next = expanded.includes(id) ? expanded.filter((item) => item !== id) : [...expanded, id];
    expanded = next;
    if (persisted) persisted.expanded = next;
    if (next.includes(id) && !files[id]) {
      try {
        const list = await gitCommitFiles(path, id);
        files = { ...files, [id]: list };
        if (persisted) persisted.files = files;
      } catch (e) {
        error = String(e);
      }
    }
  }

  /** 全部展开: 只补取还没拿到的那些提交的文件列表。 */
  async function expandAll(): Promise<void> {
    const path = projectPath;
    if (!path) return;
    const ids = commits.map((commit) => commit.id);
    expanded = ids;
    if (persisted) persisted.expanded = ids;

    const missing = commits.filter((commit) => !files[commit.id]);
    const results = await Promise.allSettled(missing.map((commit) => gitCommitFiles(path, commit.id)));
    const merged = { ...files };
    let failure: unknown = null;
    results.forEach((result, index) => {
      if (result.status === 'fulfilled') merged[missing[index]!.id] = result.value;
      else if (failure === null) failure = result.reason;
    });
    files = merged;
    if (persisted) persisted.files = merged;
    if (failure !== null) error = String(failure);
  }

  function collapseAll(): void {
    expanded = [];
    if (persisted) persisted.expanded = [];
  }

  /** 切换分支: 切换后刷新状态、提交列表、分支列表与已打开的干净文档。 */
  async function switchBranch(nextBranch: string): Promise<void> {
    const path = projectPath;
    if (busy || !path || nextBranch === branch) return;
    busy = true;
    error = null;
    try {
      await gitSwitchBranch(path, nextBranch);
      const [nextStatus, nextCommits, nextBranches] = await Promise.all([
        getGitStatus(path),
        gitLog(path),
        gitLocalBranches(path),
      ]);
      // 切换期间用户可能已经关掉/换了项目, 那就不要把结果写回去
      if (appStore.projectPath === path) appStore.setGitStatus(nextStatus);
      commits = nextCommits;
      branches = nextBranches;
      expanded = [];
      files = {};
      if (persisted) persisted = { ...persisted, commits: nextCommits, expanded: [], files: {}, scrollTop: 0 };
      if (list) list.scrollTop = 0;

      /*
       * 刷新**干净的**已打开文档: 它们在磁盘上的内容已经被工作区换了, 不刷新的话编辑器里
       * 还是上一个分支的内容。有未保存改动的文档一律跳过 —— 覆盖会吃掉用户的字。
       */
      const clean = appStore.documents.filter((document) => !document.dirty);
      const refreshed = await Promise.allSettled(
        clean.map(async (document) => ({
          path: document.path,
          content: await fs.readTextLossy(document.path),
        }))
      );
      const failed: string[] = [];
      refreshed.forEach((result, index) => {
        if (result.status === 'fulfilled') {
          appStore.updateDocument(result.value.path, { content: result.value.content, dirty: false });
        } else {
          failed.push(`${clean[index]!.name}: ${String(result.reason)}`);
        }
      });
      if (failed.length > 0) error = `分支已切换，但部分打开文档无法刷新：${failed.join('；')}`;
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }

  /**
   * 请求切换分支。
   *
   * 工作区不干净时先给一个确认 —— Git 可能直接拒绝 (会覆盖本地改动), 而如果它不拒绝,
   * 未保存的编辑器内容也可能被磁盘上的新内容顶掉。因此把三项计数讲清楚再问。
   */
  function requestBranchSwitch(nextBranch: string): void {
    branchMenu = null;
    if (nextBranch === branch || busy) return;
    const staged = gitStatus?.staged.length ?? 0;
    const unstaged = gitStatus?.unstaged.length ?? 0;
    const dirty = documents.filter((document) => document.dirty).length;
    if (staged === 0 && unstaged === 0 && dirty === 0) {
      void switchBranch(nextBranch);
      return;
    }
    requestConfirm({
      title: '切换分支',
      description:
        `当前有 ${staged} 个暂存项、${unstaged} 个未暂存项和 ${dirty} 个未保存的编辑器文档。` +
        `要切换到「${nextBranch}」吗？Git 若检测到切换会覆盖文件，将阻止操作。`,
      confirmLabel: '切换',
      action: () => void switchBranch(nextBranch),
    });
  }

  /** 还原一组文件到某个提交。 */
  async function runRestore(action: () => Promise<unknown>): Promise<void> {
    const path = projectPath;
    if (busy || !path) return;
    busy = true;
    error = null;
    try {
      await action();
      await refreshGitStatus(path);
      expanded = [];
      if (persisted) persisted.expanded = [];
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }

  const branchMenuItems = $derived<ContextMenuItem[]>(
    branches.map((name) => ({
      key: name,
      label: name,
      iconName: name === branch ? 'Checkmark' : undefined,
      disabled: busy || name === branch,
      onClick: () => requestBranchSwitch(name),
    }))
  );

  const menuItems = $derived<ContextMenuItem[]>(
    menu
      ? (() => {
          const items: ContextMenuItem[] = [];
          const isExpanded = expanded.includes(menu!.commitId);
          items.push({
            key: 'toggle',
            label: isExpanded ? '折叠' : '展开',
            iconName: isExpanded ? 'ChevronUp' : 'ChevronDown',
            onClick: () => void toggle(menu!.commitId),
          });
          items.push({ key: 'separator-toggle', separator: true });
          items.push({
            key: 'expand-all',
            label: '全部展开',
            iconName: 'ChevronDown',
            disabled: commits.length > 0 && commits.every((commit) => expanded.includes(commit.id)),
            onClick: () => void expandAll(),
          });
          items.push({
            key: 'collapse-all',
            label: '全部折叠',
            iconName: 'ChevronUp',
            disabled: commits.every((commit) => !expanded.includes(commit.id)),
            onClick: collapseAll,
          });
          items.push({ key: 'separator-restore', separator: true });
          const file = menu!.file;
          if (file) {
            items.push({
              key: 'restore',
              label: '还原',
              iconName: 'ArrowClockwise',
              onClick: () => void runRestore(() => gitRestore(projectPath as string, [file.path], menu!.commitId)),
            });
          }
          items.push({
            key: 'restoreAll',
            label: '还原全部',
            iconName: 'History',
            onClick: () => void runRestore(() => gitRestoreAll(projectPath as string, menu!.commitId)),
          });
          return items;
        })()
      : []
  );
</script>

<svelte:window
  onkeydown={(event) => {
    // 菜单打开时 Esc 先关菜单 (由 AppDialog 处理"关对话框"那一层)
    if (event.key === 'Escape' && (menu || branchMenu)) {
      menu = null;
      branchMenu = null;
    }
  }}
/>

<!--
  分支选择器放在标题栏右侧 (`titleExtra`): 它是这个对话框的"上下文", 不是一项操作 ——
  放在底栏会和"关闭"混在一起, 放在列表上方会占掉本来就紧张的高度。
  snippet 必须声明在 `<AppDialog>` **之前**: 它按块作用域解析, 写在后面会报
  "used before its declaration"。
-->
{#snippet branchPicker()}
  <button
    type="button"
    class="file-tree-path history-branch-picker"
    title={branch ?? '当前分支'}
    aria-haspopup="menu"
    aria-expanded={branchMenu !== null}
    disabled={busy || branches.length === 0}
    onclick={(event) => {
      const bounds = event.currentTarget.getBoundingClientRect();
      branchMenu = { x: bounds.left, y: bounds.bottom };
    }}
  >
    <Icon name="BranchFork" size={14} />
    <span class="file-tree-path-label">{branch ?? '当前分支'}</span>
    <Icon name="ChevronDown" size={12} />
  </button>
{/snippet}

<AppDialog title="提交历史" iconName="History" size="medium" height={620} compact {onClose} titleExtra={branchPicker}>
  <div class="history-list git-history-list dialog-scroll" bind:this={list} onscroll={onScroll}>
    {#if loading}
      <div class="muted repository-empty-list">正在同步提交历史…</div>
    {:else if commits.length === 0}
      <div class="muted repository-empty-list">暂无提交记录</div>
    {:else}
      {#each commits as commit (commit.id)}
        <div class="git-commit">
          <div
            class="git-commit-row"
            role="button"
            tabindex="0"
            onclick={() => void toggle(commit.id)}
            onkeydown={(event) => {
              if (event.key !== 'Enter' && event.key !== ' ') return;
              event.preventDefault();
              void toggle(commit.id);
            }}
            oncontextmenu={(event) => {
              event.preventDefault();
              // 贴边收拢交给 ContextMenu (它按实测尺寸算)
              menu = { commitId: commit.id, x: event.clientX, y: event.clientY };
            }}
          >
            <span class="git-commit-toggle">{expanded.includes(commit.id) ? '▾' : '▸'}</span>
            <span class="git-commit-summary" title={commit.summary}>
              {middleEllipsis(commit.summary, 60)}
            </span>
            <span class="git-commit-time">{formatDate(commit.time)}</span>
            <span class="git-file-stats">
              {#if commit.additions > 0}<em class="git-add">+{commit.additions}</em>{/if}
              {#if commit.deletions > 0}<em class="git-del">-{commit.deletions}</em>{/if}
            </span>
          </div>

          {#if expanded.includes(commit.id)}
            <div class="git-commit-detail">
              <div class="git-commit-detail-info">
                <pre class="git-commit-message">{commit.message}</pre>
                <div class="git-commit-meta">
                  <span>ID: {commit.id}</span>
                  <span>作者: {commit.author}</span>
                </div>
              </div>
              <div class="git-commit-detail-files">
                {#each files[commit.id] ?? [] as file (file.path)}
                  <button
                    type="button"
                    class="git-file-item"
                    title={file.path}
                    onclick={() => {
                      openGitDiff(file.path, 'commit', commit.id, baseName(file.path));
                      // 开差异后自动关掉历史 (保留状态, 因此不走 manualClose)
                      onClose();
                    }}
                    oncontextmenu={(event) => {
                      event.preventDefault();
                      menu = { file, commitId: commit.id, x: event.clientX, y: event.clientY };
                    }}
                  >
                    <span class="git-file-status {STATUS_CLASS[file.status] ?? ''}">{file.status}</span>
                    <span class="git-file-name">{middleEllipsis(file.path, 40)}</span>
                    <span class="git-file-stats">
                      {#if file.additions > 0}<em class="git-add">+{file.additions}</em>{/if}
                      {#if file.deletions > 0}<em class="git-del">-{file.deletions}</em>{/if}
                    </span>
                  </button>
                {/each}
              </div>
            </div>
          {/if}
        </div>
      {/each}
    {/if}
  </div>

  {#snippet footer()}
    {#if error}
      <span class="prompt-error history-error">{error}</span>
      <Button onclick={() => (error = null)}>清除</Button>
    {/if}
    <Button appearance="primary" disabled={busy} onclick={manualClose}>关闭</Button>
  {/snippet}
</AppDialog>

{#if menu}
  <ContextMenu x={menu.x} y={menu.y} items={menuItems} onClose={() => (menu = null)} />
{/if}

{#if branchMenu}
  <ContextMenu x={branchMenu.x} y={branchMenu.y} items={branchMenuItems} onClose={() => (branchMenu = null)} />
{/if}
